package codegen

import (
	"fmt"
	"go/format"
	"slices"
	"strconv"
	"strings"

	"github.com/syssam/velox/plugin"
)

// header starts every file velox-gen writes: velox-gen rewrites and deletes
// only files that start with it.
const header = "// Code generated by velox-gen. DO NOT EDIT.\n\n"

// File is one generated file.
type File struct {
	Name string // e.g. "user.go", "velox.go"
	Data []byte // gofmt-formatted
}

// Generate is Lower then Render.
func Generate(g *Graph, cfg Config) ([]File, error) {
	o, err := Lower(g, cfg)
	if err != nil {
		return nil, err
	}
	return Render(o)
}

// Render writes one file per entity, entityFile's (the join entities too),
// and velox.go: the package comment and the enums.
//
// The files are in the order of o.Entities, then velox.go. Render does not
// change o, and the same o gives the same bytes.
func Render(o *Out) ([]File, error) {
	files := make([]File, 0, len(o.Entities)+1)
	add := func(name, src string) error {
		data, err := formatted(name, src)
		if err != nil {
			return err
		}
		files = append(files, File{Name: name, Data: data})
		return nil
	}
	for _, e := range o.Entities {
		if err := add(entityFile(e.Label), renderEntity(o, e)); err != nil {
			return nil, err
		}
	}
	if err := add("velox.go", renderPackage(o)); err != nil {
		return nil, err
	}
	return files, nil
}

// entityFile is the Go file of the entity labelled label: <label>.go, as
// ent names it, or <label>_velox.go when go build would leave <label>.go out
// of some builds, by a _test, _GOOS or _GOARCH suffix, or when it is
// velox.go, the package's own file.
func entityFile(label string) string {
	name := label + ".go"
	if sys, _ := GoFileSystems(name, []byte("package p\n"), ""); sys != EverySystem || name == "velox.go" {
		return label + "_velox.go"
	}
	return name
}

func formatted(name, src string) ([]byte, error) {
	b, err := format.Source([]byte(src))
	if err != nil {
		return nil, fmt.Errorf("formatting %s: %w\n%s", name, err, src)
	}
	return b, nil
}

// writer builds the text of a file.
type writer struct{ strings.Builder }

func (w *writer) p(format string, args ...any) {
	_, _ = fmt.Fprintf(w, format, args...)
	w.WriteByte('\n')
}

// doc writes text as a doc comment at the current indentation.
func (w *writer) doc(text string) {
	for l := range strings.SplitSeq(strings.TrimRight(text, "\n"), "\n") {
		w.p("//%s", strings.TrimRight(" "+l, " "))
	}
}

// camel is the identifier of a label in the names of an entity's variable and
// function: user_group → userGroup, http_log → httpLog.
func camel(label string) string {
	first, rest, ok := strings.Cut(label, "_")
	if !ok {
		return label
	}
	return first + plugin.GoName(rest)
}

// renderPackage writes velox.go, with the package comment unless a user's
// file has it.
func renderPackage(o *Out) string {
	var w writer
	w.WriteString(header)
	if !o.UserDoc {
		w.p("// Package %s holds the entities of %s, generated by velox-gen.", o.Package, o.SchemaPath)
	}
	w.p("package %s", o.Package)
	w.p("")
	w.p(`import "github.com/syssam/velox"`)
	w.p("")
	w.p("const _ = velox.GeneratedCodeIsVersion%d", GeneratedCodeVersion)
	if o.EntityTable {
		entityTable(&w, o)
	}
	for _, en := range o.Enums {
		w.p("")
		w.p("// %s is the type of %s.", en.Type, en.Of)
		w.p("type %s string", en.Type)
		w.p("")
		w.p("// The values of %s.", en.Type)
		w.p("const (")
		for i, c := range en.Consts {
			w.p("%s %s = %s", c, en.Type, strconv.Quote(en.Values[i]))
		}
		w.p(")")
		w.p("")
		w.p("// Values returns the values of %s in declaration order.", en.Type)
		w.p("func (e %s) Values() []string { return []string{%s} }", en.Type, quoteAll(en.Values))
		w.p("")
		w.p("// String returns the stored value of e.")
		w.p("func (e %s) String() string { return string(e) }", en.Type)
		w.p("")
		w.p("// IsValid reports whether e is one of the values of %s.", en.Type)
		w.p("func (e %s) IsValid() bool {", en.Type)
		w.p("\tswitch e {")
		w.p("\tcase %s:", strings.Join(en.Consts, ", "))
		w.p("\t\treturn true")
		w.p("\t}")
		w.p("\treturn false")
		w.p("}")
	}
	return w.String()
}

// entityTable writes the package's velox.EntityTable: every entity, by its
// name in the schema and its table, built on first use. A condition by name,
// velox.HasEdge, HasEdgeWith and FieldInSelect, finds its target in it when
// its statement runs.
func entityTable(w *writer, o *Out) {
	w.p("")
	w.p("var veloxEntities velox.EntityTable")
	w.p("")
	w.p("// veloxEntityTable is called by velox, not by applications.")
	w.p("func veloxEntityTable() *velox.EntityTable {")
	w.p("\treturn veloxEntities.Load(func() []velox.EntityLink {")
	w.p("\t\treturn []velox.EntityLink{")
	for _, e := range o.Entities {
		w.p("\t\t\tvelox.LinkEntity[%s](%s, %s),", e.Name, strconv.Quote(e.Name), strconv.Quote(e.Table))
	}
	w.p("\t\t}")
	w.p("\t})")
	w.p("}")
}

func quoteAll(ss []string) string {
	q := make([]string, len(ss))
	for i, s := range ss {
		q[i] = strconv.Quote(s)
	}
	return strings.Join(q, ", ")
}

// renderEntity writes the file of e.
func renderEntity(o *Out, e *OutEntity) string {
	var w writer
	w.WriteString(header)
	w.p("package %s", o.Package)
	w.p("")
	entityImports(&w, o, e)
	entityStruct(&w, e)
	w.p("")
	entityPositions(&w, e)
	entityHandles(&w, e)
	w.p("")
	id := camel(e.Label)
	w.p("var %sMeta velox.MetaOnce[%s]", id, e.Name)
	w.p("")
	w.p("// VeloxMeta is called by velox, not by applications.")
	w.p("func (*%s) VeloxMeta() *velox.Meta[%[1]s] { return %sMeta.Load(%[2]sDescriptor) }", e.Name, id)
	w.p("")
	entityDescriptor(&w, o, e)
	w.p("")
	entityString(&w, e)
	return w.String()
}

// entityImports writes the import declaration: the standard packages first,
// then the others, velox and the schema package among them.
func entityImports(w *writer, o *Out, e *OutEntity) {
	std := []string{"fmt"} // String uses fmt
	other := []string{"github.com/syssam/velox"}
	for _, p := range e.Imports {
		if first, _, _ := strings.Cut(p, "/"); strings.Contains(first, ".") {
			other = append(other, p)
		} else {
			std = append(std, p)
		}
	}
	slices.Sort(std)
	slices.Sort(other)
	w.p("import (")
	for _, p := range slices.Compact(std) {
		w.p("%s", strconv.Quote(p))
	}
	w.p("")
	for _, p := range slices.Compact(other) {
		if n := e.ImportAs[p]; n != "" {
			w.p("%s %s", n, strconv.Quote(p))
		} else {
			w.p("%s", strconv.Quote(p))
		}
	}
	if e.NeedsSch {
		if o.SchemaName != guessName(o.SchemaPath) {
			w.p("%s %s", o.SchemaName, strconv.Quote(o.SchemaPath))
		} else {
			w.p("%s", strconv.Quote(o.SchemaPath))
		}
	}
	w.p(")")
	w.p("")
}

// namesFirst reports whether the doc comment text starts with name, or
// with an article and name, as Go's doc comments do.
func namesFirst(text, name string) bool {
	for _, lead := range []string{"", "A ", "An ", "The "} {
		if rest, ok := strings.CutPrefix(text, lead+name); ok && (rest == "" || !isIdentRune(rest[0])) {
			return true
		}
	}
	return false
}

// isIdentRune reports whether b may continue an identifier.
func isIdentRune(b byte) bool {
	return b == '_' || '0' <= b && b <= '9' || 'a' <= b && b <= 'z' || 'A' <= b && b <= 'Z'
}

// entityStruct writes the struct of e, its fields and then its Edges, and the
// struct of its relations, XEdges, when it has any.
func entityStruct(w *writer, e *OutEntity) {
	switch {
	case e.Comment != "" && namesFirst(e.Comment, e.Name):
		w.doc(e.Comment)
	case e.Comment != "":
		// Go's doc comments start with the name they document.
		w.p("// %s is the entity of schema %[1]s.", e.Name)
		w.p("//")
		w.doc(e.Comment)
	case e.Join:
		w.p("// %s is the join entity of table %s.", e.Name, e.Table)
	default:
		w.p("// %s is the entity of schema %[1]s.", e.Name)
	}
	w.p("type %s struct {", e.Name)
	for _, f := range e.Fields {
		if f.Comment != "" {
			w.doc(f.Comment)
		}
		w.p("%s %s %s", f.GoName, f.GoType, f.Tag)
	}
	if len(e.Rels) > 0 {
		w.p("// Edges holds %s's relations, filled by With.", e.Name)
		w.p("Edges %sEdges `json:\"edges,omitzero\"`", e.Name)
	}
	w.p("}")
	if len(e.Rels) == 0 {
		return
	}
	w.p("")
	w.p("// %sEdges holds the relations of %[1]s, filled by With.", e.Name)
	w.p("type %sEdges struct {", e.Name)
	for _, r := range e.Rels {
		kind := "One"
		if r.Many {
			kind = "Many"
		}
		if r.Comment != "" {
			w.doc(r.Comment)
		} else {
			w.p("// %s holds the edge %s, to %s, loaded by With(%s.%[1]s).", r.GoName, r.Name, r.Target, e.Handles)
		}
		w.p("%s velox.%s[%s] `json:\"%s,omitzero\"`", r.GoName, kind, r.Target, r.Name)
	}
	w.p("}")
}

// entityPositions writes the constants of e's columns' and edges' positions,
// which the handles, the descriptor and Check share, so that none of them
// holds a bare number.
func entityPositions(w *writer, e *OutEntity) {
	w.p("// The positions of %s's columns, in the order of its table.", e.Name)
	w.p("const (")
	for i := range e.Fields {
		if i == 0 {
			w.p("%s = iota", colConst(e, i))
		} else {
			w.p("%s", colConst(e, i))
		}
	}
	w.p(")")
	w.p("")
	if len(e.Rels) == 0 {
		return
	}
	w.p("// The positions of %s's edges.", e.Name)
	w.p("const (")
	for i := range e.Rels {
		if i == 0 {
			w.p("%s = iota", edgeConst(e, i))
		} else {
			w.p("%s", edgeConst(e, i))
		}
	}
	w.p(")")
	w.p("")
}

// entityHandles writes the variable of the typed handles of e's columns and
// relations, and its type, XHandles: exported, so that go doc lists the
// handles with their comments.
func entityHandles(w *writer, e *OutEntity) {
	typ := e.Name + "Handles"
	what := "columns"
	if len(e.Rels) > 0 {
		what = "columns and relations"
	}
	w.p("// %s is the type of %s, the typed handles of %s's %s.", typ, e.Handles, e.Name, what)
	w.p("type %s struct {", typ)
	for _, f := range e.Fields {
		w.p("// %s is the column %s.", f.GoName, f.Column)
		w.p("%s %s", f.GoName, f.Handle)
	}
	for _, r := range e.Rels {
		w.p("// %s is the edge %s, to %s: With loads it, Has and HasWith test it.", r.GoName, r.Name, r.Target)
		w.p("%s velox.Rel[%s, %s]", r.GoName, e.Name, r.Target)
	}
	w.p("}")
	w.p("")
	w.p("// %s holds the typed handles of %s's %s.", e.Handles, e.Name, what)
	w.p("var %s = %s{", e.Handles, typ)
	for i, f := range e.Fields {
		w.p("%s: %s{I: %s},", f.GoName, f.Handle, colConst(e, i))
	}
	for i, r := range e.Rels {
		w.p("%s: velox.Rel[%s, %s]{I: %s},", r.GoName, e.Name, r.Target, edgeConst(e, i))
	}
	w.p("}")
}

// entityDescriptor writes the function that returns e's Descriptor.
// columnParts is the fields of f's ColumnDescriptor literal, in order.
func columnParts(f *OutField) []string {
	parts := []string{"Field: " + strconv.Quote(f.GoName), "Name: " + strconv.Quote(f.Column)}
	if f.DefaultCode != "" {
		parts = append(parts, "Default: "+f.DefaultCode)
	}
	if f.DefaultFuncCode != "" {
		parts = append(parts, "DefaultFunc: "+f.DefaultFuncCode)
	}
	if f.UpdateDefaultCode != "" {
		parts = append(parts, "UpdateDefault: "+f.UpdateDefaultCode)
	}
	if f.Immutable {
		parts = append(parts, "Immutable: true")
	}
	if f.Version {
		parts = append(parts, "Version: true")
	}
	if f.Sensitive {
		parts = append(parts, "Sensitive: true")
	}
	if f.NilIsNull {
		parts = append(parts, "Nullable: true")
	}
	if f.RequiredEdge != "" {
		parts = append(parts, "RequiredEdge: "+strconv.Quote(f.RequiredEdge))
	}
	if f.JSON {
		parts = append(parts, "Encode: json.Marshal", "Decode: json.Unmarshal")
	}
	return parts
}

func entityDescriptor(w *writer, o *Out, e *OutEntity) {
	w.p("// %sDescriptor describes %s to velox: its table, columns, edges and hooks.", camel(e.Label), e.Name)
	w.p("func %sDescriptor() velox.Descriptor[%s] {", camel(e.Label), e.Name)
	if e.CheckSetup != "" {
		w.p("%s", e.CheckSetup)
	}
	w.p("return velox.Descriptor[%s]{", e.Name)
	w.p("Table: %s,", strconv.Quote(e.Table))
	if e.TableSchema != "" {
		w.p("TableSchema: %s,", strconv.Quote(e.TableSchema))
	}
	w.p("Columns: []velox.ColumnDescriptor{")
	for _, f := range e.Fields {
		w.p("%s,", literal(columnParts(f)))
	}
	w.p("},")
	w.p("PrimaryKey: %s,", cols(e, e.PrimaryKey))
	if e.Bidi {
		w.p("Bidi: true,")
	}
	if len(e.Indexes) > 0 {
		w.p("Indexes: []velox.IndexInfo{")
		for _, ix := range e.Indexes {
			names := make([]string, len(ix.Columns))
			for i, c := range ix.Columns {
				names[i] = e.Fields[c].Column
			}
			if ix.Unique {
				w.p("{Columns: %s, Unique: true}, // %s", cols(e, ix.Columns), strings.Join(names, ", "))
			} else {
				w.p("{Columns: %s}, // %s", cols(e, ix.Columns), strings.Join(names, ", "))
			}
		}
		w.p("},")
	}
	if len(e.Rels) > 0 {
		w.p("Edges: []velox.EdgeDescriptor{")
		for _, r := range e.Rels {
			w.p("%s,", r.Desc)
		}
		w.p("},")
	}
	if o.EntityTable {
		w.p("Entities: veloxEntityTable,")
	}
	// velox reads the behaviour of the schema's mixins, in Mixin order,
	// then the schema's own.
	if e.Schema != "" {
		w.p("Schema: %s,", e.Schema)
	}
	w.p("FieldPtr: func(x *%s, i int) any {", e.Name)
	w.p("switch i {")
	for i, f := range e.Fields {
		w.p("case %s:", colConst(e, i))
		w.p("return &x.%s", f.GoName)
	}
	w.p("}")
	w.p("return nil")
	w.p("},")
	if len(e.Rels) > 0 {
		w.p("EdgeFieldPtr: func(x *%s, i int) any {", e.Name)
		w.p("switch i {")
		for i, r := range e.Rels {
			w.p("case %s:", edgeConst(e, i))
			w.p("return &x.Edges.%s", r.GoName)
		}
		w.p("}")
		w.p("return nil")
		w.p("},")
	}
	if e.CheckCode != "" {
		w.p("Check: func(col int, v any) error {")
		w.p("switch col {")
		w.p("%s", e.CheckCode)
		w.p("}")
		w.p("return nil")
		w.p("},")
	}
	w.p("}")
	w.p("}")
}

// cols is the []int literal of the positions of e's columns is.
func cols(e *OutEntity, is []int) string {
	s := make([]string, len(is))
	for i, n := range is {
		s[i] = colConst(e, n)
	}
	return "[]int{" + strings.Join(s, ", ") + "}"
}

// entityString writes e's String and GoString methods: String prints its
// fields except the sensitive ones, a pointer field as its value, or nil, and
// a bytes field as its length, and GoString (for %#v) is the same text. Both have a value receiver, so that an
// entity value, such as an element of the []E that All returns, prints without
// its sensitive fields under %v, %+v and %#v as well as a pointer.
func entityString(w *writer, e *OutEntity) {
	var verbs, args []string
	hidden := slices.ContainsFunc(e.Fields, func(f *OutField) bool { return f.Sensitive || f.Implicit })
	if hidden {
		w.p("// String returns the entity's fields except the sensitive ones and the foreign keys velox added.")
	} else {
		w.p("// String returns the entity's fields.")
	}
	// The receiver is the first letter of the type's name, as Go names one;
	// the body names no other one-letter identifier.
	x := strings.ToLower(e.Name[:1])
	w.p("func (%s %s) String() string {", x, e.Name)
	for _, f := range e.Fields {
		if f.Sensitive || f.Implicit {
			continue
		}
		if f.ElemType == "[]byte" && !f.Pointer {
			// A blob can be megabytes: String says how long it is.
			verbs = append(verbs, f.GoName+"=<%d bytes>")
			args = append(args, "len("+x+"."+f.GoName+")")
			continue
		}
		verbs = append(verbs, f.GoName+"=%v")
		if !f.Pointer {
			args = append(args, x+"."+f.GoName)
			continue
		}
		args = append(args, "velox.Show("+x+"."+f.GoName+")")
	}
	w.p("return %s", sprintfCall(e.Name, verbs, args))
	w.p("}")
	w.p("")
	if hidden {
		w.p("// GoString is String, so that %%#v does not print them either.")
	} else {
		w.p("// GoString is String, so that %%#v prints the same text.")
	}
	w.p("func (%s %s) GoString() string { return %[1]s.String() }", x, e.Name)
}

// literal is the composite literal of the fields xs, its type elided: on
// one line when it fits in 2*lineWidth bytes, else a field a line.
func literal(xs []string) string {
	if one := "{" + strings.Join(xs, ", ") + "}"; len(one) <= 2*lineWidth-20 {
		return one
	}
	return "{\n" + strings.Join(xs, ",\n") + ",\n}"
}

// lineWidth is the most bytes sprintfCall keeps on one line.
const lineWidth = 60

// sprintfCall is the call fmt.Sprintf of the format head(verbs...) and
// args: on one line when it is short, else the format in "…"+ pieces and
// the arguments a few a line, each piece at most lineWidth bytes.
func sprintfCall(head string, verbs, args []string) string {
	format := head + "(" + strings.Join(verbs, ", ") + ")"
	one := "fmt.Sprintf(" + strconv.Quote(format)
	if len(args) > 0 {
		one += ", " + strings.Join(args, ", ")
	}
	if one += ")"; len(one) <= 2*lineWidth {
		return one
	}
	var b strings.Builder
	b.WriteString("fmt.Sprintf(" + strconv.Quote(head+"(") + "+\n")
	lines := runs(verbs, ", ")
	for i, l := range lines {
		if i < len(lines)-1 {
			b.WriteString(strconv.Quote(l+", ") + "+\n")
		} else {
			b.WriteString(strconv.Quote(l+")") + ",\n")
		}
	}
	for _, l := range runs(args, ", ") {
		b.WriteString(l + ",\n")
	}
	b.WriteString(")")
	return b.String()
}

// runs are xs joined by sep into runs of at most lineWidth bytes; an
// element longer than that is a run of its own.
func runs(xs []string, sep string) []string {
	var out []string
	cur := ""
	for _, x := range xs {
		switch {
		case cur == "":
			cur = x
		case len(cur)+len(sep)+len(x) <= lineWidth:
			cur += sep + x
		default:
			out = append(out, cur)
			cur = x
		}
	}
	if cur != "" {
		out = append(out, cur)
	}
	return out
}
